use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{collections::BTreeMap,fs,path::{Path,PathBuf},process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/euler-compact";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn libraries()->BTreeMap<String,String>{let text=fs::read_to_string(format!("{R}/native/libraries/stdout.log")).unwrap();let mut libs=BTreeMap::new();for line in text.lines(){let Ok(v)=serde_json::from_str::<Value>(line)else{continue;};if v["reason"]!="compiler-artifact"{continue;}let name=v["target"]["name"].as_str().unwrap();if !["zopro_core","zopro_bn254","rayon","serde_json","sha2","libc"].contains(&name){continue;}if let Some(files)=v["filenames"].as_array(){for f in files{let f=f.as_str().unwrap();if f.ends_with(".rlib"){if let Some(old)=libs.insert(name.to_owned(),f.into()){assert_eq!(old,f);}}}}}libs}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("native/result.json"))["status"],"complete");let fresh=libraries();let accepted=read("/home/ubuntu/src/zopro-perf-work/mixed-sdk/native-control/control/artifacts.json");let flags=fs::read_to_string(r.join("native-flags.txt")).unwrap();let mut receipts=BTreeMap::new();
    for label in["accepted","fresh","tests"]{let mut selected=BTreeMap::<String,String>::new();for name in["zopro_core","zopro_bn254","rayon","serde_json","sha2","libc"]{let p=if label=="accepted"{if name=="sha2"{let deps=Path::new(accepted["libraries"]["zopro_core"].as_str().unwrap()).parent().unwrap();let candidates:Vec<_>=fs::read_dir(deps).unwrap().map(|e|e.unwrap().path()).filter(|p|p.file_name().unwrap().to_string_lossy().starts_with("libsha2-")&&p.extension().is_some_and(|s|s=="rlib")).collect();assert_eq!(candidates.len(),1);candidates[0].display().to_string()}else{accepted["libraries"][name].as_str().unwrap().into()}}else{fresh[name].clone()};selected.insert(name.into(),p);}
        let deps=Path::new(&selected["zopro_core"]).parent().unwrap();let binary=r.join(if label=="tests"{"kernel-tests"}else if label=="accepted"{"accepted-probe"}else{"candidate-probe"});let mut args:Vec<String>=flags.split_whitespace().map(String::from).collect();args.extend(["--edition=2021".into(),"-O".into(),"-C".into(),"lto=fat".into(),"-C".into(),"codegen-units=1".into(),"-L".into(),format!("dependency={}",deps.display())]);for(name,p)in&selected{args.extend(["--extern".into(),format!("{name}={p}")]);}
        if label=="accepted"{args.extend(["--cfg".into(),"accepted_control".into()]);}if label=="tests"{args.push("--test".into());let old="/home/ubuntu/src/zopro-perf-work/paired-callers/target/release/deps";args.extend(["-L".into(),format!("dependency={old}"),"--extern".into(),format!("ark_ff={old}/libark_ff-9216c709978bd3d2.rlib"),"--extern".into(),format!("ark_bn254={old}/libark_bn254-d9ceb28748a3bfd8.rlib")]);}
        args.extend([r.join("probe-v2.rs").display().to_string(),"-o".into(),binary.display().to_string()]);save(r.join(format!("link-{label}-command.json")),&json!({"argv":args}));let output=Command::new("rustc").args(&args).output().unwrap();fs::write(r.join(format!("link-{label}-stdout.log")),&output.stdout).unwrap();fs::write(r.join(format!("link-{label}-stderr.log")),&output.stderr).unwrap();assert!(output.status.success(),"link {label} failed");
        let mut inputs=BTreeMap::new();for p in selected.values(){inputs.insert(p.clone(),hash(p));}for file in["probe-v2.rs","kernel-v2.rs","retained-output.rs","perf.rs"]{let p=r.join(file);inputs.insert(p.display().to_string(),hash(p));}receipts.insert(label,json!({"binary":binary,"sha256":hash(&binary),"libraries":selected,"input_pins":inputs}));
    }save(r.join("probe-artifacts.json"),&json!(receipts));println!("Linked accepted/fresh/kernel-tests fromexactreceipts");
}
